import {checkpoints, starter, broken, fixed, complete, alternative, binding, validate, snapshot, scriptKind, propose, applyPlan, undoPlan} from './core.js';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'▦',code:'〈〉',book:'▤',host:'◈',arrow:'↗',shield:'◇',play:'▷'};
let saved; try { saved=JSON.parse(localStorage.getItem('rejoin.workspace')); if(saved) validate(saved.files); } catch { saved=null; }
let files=saved?.files || structuredClone(starter), protections=saved?.protections || ['style.css'], active='script.js', target='C2', verified=saved?.verified || null, plan=null, undo=saved?.undo || null, tab='workspace', panel='intro', lastResult=null, dirty=false;
let room={checkpoint:'C2',paused:false,connection:'Demo mode',channel:null}, checkGeneration=0;
const checkpoint=id=>checkpoints.find(c=>c.id===id);
function toast(message){ $('#toast').textContent=message; $('#toast').classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500); }
function save(){try{localStorage.setItem('rejoin.workspace',JSON.stringify({files,protections,verified,undo}));dirty=false;const el=$('#save-state');if(el)el.textContent='Saved on this device';}catch{dirty=true;toast('Save failed. Export your project before leaving this page.');}}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
function download(name,data,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function modal(html){$('#dialog').innerHTML=html;$('#dialog').showModal();$('#dialog').querySelector('[data-close]')?.addEventListener('click',()=>$('#dialog').close());}
const button=(label,action,cls='')=>`<button class="${cls}" data-action="${action}">${label}</button>`;
function render(){
 const overlay=new URLSearchParams(location.search).has('overlay');
 if(overlay){$('#app').innerHTML=`<main class="overlay"><div class="brand"><b>↳</b> rejoin<span class="pill">${esc(room.connection)}</span></div><h1>Build something. Together.</h1><p>${esc(room.checkpoint)} · ${esc(checkpoint(room.checkpoint).title)}</p><small>Community RSVP workshop · Aggregate progress unavailable</small></main>`;return;}
 $('#app').innerHTML=`<aside class="rail"><a class="brand-mark" href="/" aria-label="Rejoin home">↳</a><div class="rail-links">${[['workspace','code','Workspace'],['lesson','book','Lesson guide'],['host','host','Instructor view']].map(([t,i,n])=>`<button class="rail-btn ${tab===t?'selected':''}" data-tab="${t}" aria-label="${n}" title="${n}">${icons[i]}</button>`).join('')}</div><button class="rail-btn" data-action="privacy" title="Privacy and settings" aria-label="Privacy and settings">⚙</button><div class="avatar">A</div></aside>
 <div class="shell"><header><a href="/" class="wordmark">rejoin<span> / </span><small>workshop</small></a><div class="header-right"><span class="private">◇ Private workspace</span><button class="quiet" data-action="guide">Quick guide <span>↗</span></button><span class="avatar small">A</span></div></header>
 <main><div class="breadcrumb">COMMUNITY WORKSHOPS <span>/</span> BUILD ALONG</div><div class="page-heading"><div><h1>Your place in the stream.</h1><p>Keep building. Get unstuck. Make it yours.</p></div><div class="heading-actions">${button('↓ Export project','export','secondary')}${button('Watch on Twitch ↗','twitch','twitch-btn')}</div></div>
 <section class="stream-bar"><div class="stream-avatar">〈/〉<i></i></div><div class="stream-title"><strong>Build a community RSVP page</strong><span>HTML, CSS & JavaScript <b>·</b> Beginner friendly <b>·</b> Prepared workshop</span></div><span class="pill purple">${room.connection==='Connected'?'TWITCH CONNECTED':'DEMO WORKSHOP'}</span><div class="stream-current"><span>INSTRUCTOR CHECKPOINT</span><strong>${esc(room.checkpoint)} <b>·</b> ${esc(checkpoint(room.checkpoint).title)}</strong></div></section>
 ${tab==='workspace'?workspace():tab==='lesson'?lesson():host()}
 <footer><span><i class="purple-dot"></i> ${esc(room.connection)} <span class="muted">·</span> ${room.paused?'Workshop paused':'Your code stays on this device'}</span><span>Made for the moments between “wait…” and “got it.” <b>↳</b></span></footer></main></div>`;
 bind(); if(tab==='workspace'){renderPanel(); updatePreview();}
}
function workspace(){return `<div class="checkpoint-strip">${checkpoints.map((c,i)=>`<button class="checkpoint ${target===c.id?'active':''}" data-target="${c.id}"><span class="step-number">${verified===c.id?'✓':String(i+1).padStart(2,'0')}</span><span><small>CHECKPOINT ${i+1}</small><strong>${c.title}</strong></span>${room.checkpoint===c.id?'<em>INSTRUCTOR</em>':''}${target===c.id?'<span class="target-dot">●</span>':''}</button>`).join('')}</div>
 <div class="work-layout"><section class="studio"><div class="studio-heading"><div><span class="tiny-icon">〈〉</span><strong>Your workspace</strong><span class="label">LOCAL</span></div><span id="save-state">Saved on this device</span></div><div class="editor-toolbar"><div class="file-tabs">${Object.keys(files).map(f=>`<button class="file-tab ${active===f?'active':''}" data-file="${f}"><span class="file-icon ${f.endsWith('js')?'js':''}">${f.endsWith('js')?'JS':f.endsWith('css')?'#':'◇'}</span>${f}${protections.includes(f)?'<span class="lock">◇</span>':''}</button>`).join('')}</div><button data-action="protect" class="protect" aria-pressed="${protections.includes(active)}" title="Protect this file">◇ ${protections.includes(active)?'Protected':'Protect file'}</button></div><div class="editor"><div id="line-numbers" aria-hidden="true">${files[active].split('\n').map((_,i)=>`<span>${i+1}</span>`).join('')}</div><textarea id="code" spellcheck="false" aria-label="${active} source code" wrap="off">${esc(files[active])}</textarea></div><div class="editor-status"><span>${esc(active)} <b>·</b> UTF-8</span><span>Tab moves to next control <b>·</b> ${files[active].split('\n').length} lines</span></div>
 <div class="preview-toolbar"><strong><span>◉</span> Preview</strong><span class="preview-url">localhost / your-community</span><button data-action="run" class="quiet">↻ Run checks</button></div><div class="preview-wrap"><iframe id="preview" title="Isolated prepared workshop preview" sandbox="allow-scripts" referrerpolicy="no-referrer"></iframe></div><div class="preview-bottom"><span id="preview-state">Prepared-workshop preview</span><span>◇ Restricted execution</span></div></section>
 <aside class="recovery"><div class="recovery-top"><span class="spark">✧</span><strong>A little help, a lot more you.</strong><span class="label">REJOIN</span></div><div id="recovery-content"></div><div class="recovery-foot">◇ Your changes are yours. Always.</div></aside></div><div class="bottom-note"><span>◇ <strong>Your progress, at your pace.</strong> Live: ${esc(room.checkpoint)} <span>·</span> Last verified: ${verified||'not yet'} <span>·</span> Recovery target: ${target}</span>${button('↶ Undo last fix','undo','quiet')}</div>`;}
function lesson(){return `<section class="guide-grid">${checkpoints.map(c=>`<article class="guide-card"><span class="pill purple">${c.id} · v1.0</span><h2>${c.title}</h2><p>${c.detail}</p><p>${c.id==='C1'?'Personalize the event title in index.html and the colors in style.css.':c.id==='C2'?'A function describes what should happen. An event listener decides when it happens. Connect the click to register.':'Use textContent to update the count after registration. The status region announces confirmation to screen readers.'}</p>${button('Practice this checkpoint →','practice-'+c.id,'primary')}</article>`).join('')}</section><div class="info-banner">A prepared, fictional community event. No registrations, email addresses or payments are collected.</div>`;}
function host(){return `<div class="host-grid"><section class="guide-card"><span class="eyebrow">INSTRUCTOR CONSOLE</span><h2>Keep your community together.</h2><p>Local controls are a rehearsal. With the connector running, authenticated broadcaster commands set the live checkpoint.</p><div class="host-controls">${checkpoints.map(c=>button(c.id+' · '+c.title,'host-'+c.id,'secondary')).join('')}</div>${button(room.paused?'Resume rehearsal':'Pause rehearsal','pause','secondary')}<div class="info-banner">${esc(room.connection)}. No live participant statistics are collected. Private code never appears here.</div></section><section class="guide-card"><span class="eyebrow">STREAM TOOLS</span><h2>Teach once. Help everyone.</h2><p><code>!checkpoint C2</code> Move the live checkpoint (host only).</p><p><code>!pause</code> Pause new recovery requests (host only).</p><p><code>!rejoin</code> Surface the public join route in the connector.</p><p class="muted">Learner identity linking and !stuck / !ready are not enabled in this build.</p><a class="primary link-button" href="/?overlay=1" target="_blank" rel="noopener">Open OBS overlay ↗</a></section></div><div class="guide-card"><h3>Privacy comes before a progress chart.</h3><p>0 shared progress reports. No public breakdown is shown without at least five opted-in learners. This build does not send learner progress.</p></div>`;}
function renderPanel(){const p=$('#recovery-content');if(!p)return;
 const intro=`<div class="orbit"><span>↳</span><i>✦</i><b>+</b></div><span class="eyebrow">A WAY BACK, NOT A START OVER</span><h2>Lost the thread?<br>Let’s pick it back up.</h2><p>A missing line shouldn’t mean losing your whole project. Find your next step and keep the parts that make it yours.</p><div class="target-card"><span>YOUR RECOVERY TARGET</span><strong><i>${target}</i> ${checkpoint(target).title}</strong><small>${checkpoint(target).detail}</small></div><div class="promise"><span>◇</span><div><strong>Keep your personal touches</strong><small>Your title, colors and protected files stay yours.</small></div></div>${button('✧ Help me continue →','help','primary full')}<small class="fineprint">Instructor-authored assistance · no code upload</small><div class="divider"></div><div class="mini-title">TAKE A DIFFERENT ROUTE</div>${button('Read the lesson guide <span>↗</span>','lesson','text-row')}${button('Prepare a question for the host <span>↗</span>','handoff','text-row')}`;
 if(panel==='intro')p.innerHTML=intro;
 else if(panel==='consent')p.innerHTML=`<span class="eyebrow">YOU’RE IN CONTROL</span><h2>Review what we’ll check.</h2><p>This prepared-workshop helper runs locally. These three files stay in this browser; no model or instructor receives them.</p><div class="review-files">${Object.keys(files).map(f=>`<div><span>${f}</span><small>${protections.includes(f)?'◇ Protected':'Read locally'}</small></div>`).join('')}</div><p class="fineprint">Supported: three UTF-8 HTML, CSS and JavaScript files, up to 100 KB each. Only prepared JavaScript patterns can run. Unfamiliar code remains editable and exportable.</p>${button('Show me a hint →','hint','primary full')}${button('Cancel','cancel','quiet full')}`;
 else if(panel==='hint')p.innerHTML=`<span class="eyebrow">ONE SMALL NEXT STEP</span><h2>A function needs<br>an invitation.</h2><p>The <code>register()</code> function tells the page what to do. But what tells it <em>when</em> to do it?</p><div class="hint-box"><strong>Try this</strong><p>Find the button’s click event binding in <code>script.js</code>. Connect it to <code>register</code> without calling the function immediately.</p></div><p class="fineprint">${target==='C3'?'For C3, also update #count inside register().':''} This is an authored hint for the prepared defect, not an AI diagnosis.</p>${button('Review a suggested fix →','suggest','primary full')}${button('I’ll try it myself','cancel','quiet full')}`;
 else if(panel==='plan')p.innerHTML=`<div class="review-label">◇ REVIEW BEFORE APPLYING</div><h2>${plan.state==='candidate'?'A small fix.<br>Your project intact.':plan.state==='conflict'?'Your protection<br>comes first.':plan.state==='no-change'?'No rewrite needed.':'Let’s get another<br>pair of eyes.'}</h2>${plan.state==='candidate'?`<p>${target==='C2'?'Connect the button’s click event to your registration function.':'Connect registration and update the attendee count.'} Your HTML and CSS remain byte-for-byte unchanged.</p><div class="diff"><div>script.js <span>Proposed change</span></div><pre class="removed">− ${esc(plan.removed)}</pre><pre class="added">+ ${esc(plan.added)}</pre></div><details class="full-diff"><summary>Review exact file before and after</summary><strong>Before</strong><pre>${esc(JSON.parse(plan.before)['script.js'])}</pre><strong>After</strong><pre>${esc(plan.files['script.js'])}</pre></details><ul class="check-list"><li>◇ Event title unchanged</li><li>◇ Styles and colors unchanged</li><li>◇ Protected files untouched</li></ul><div class="check-result" id="candidate-result">${esc(lastResult?.message||'Behavioral checks have not run yet.')}</div>${button('Check suggestion','check-candidate','secondary full')}${button('Approve & apply this fix →','apply','primary full')}`:`<p>${esc(plan.message)}</p>${button('Prepare a help packet','handoff','primary full')}`} ${button('Back to my workspace','cancel','quiet full')}`;
 else if(panel==='done')p.innerHTML=`<div class="success-orbit">↳</div><span class="eyebrow">YOUR NEXT STEP IS WAITING</span><h2>${lastResult?.passed?'Back in the flow.':'Fix applied.<br>Checks need attention.'}</h2><p>${esc(lastResult?.message||'Run checks to confirm the result.')}</p><ul class="check-list"><li>◇ Your event title was preserved</li><li>◇ Your styles were preserved</li><li>↶ Your previous version is available</li></ul><div class="hint-box"><strong>A quick thought, if you like</strong><p>Why do we pass <code>register</code>, rather than <code>register()</code>, to the listener?</p>${button('Reveal explanation','answer','quiet')}</div>${button('Keep building →','cancel','primary full')}${button('Undo this fix','undo','quiet full')}`;
 p.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action)));
}
function bind(){document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;render();});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-target]').forEach(el=>el.onclick=()=>{target=el.dataset.target;plan=null;panel='intro';render();});document.querySelectorAll('[data-file]').forEach(el=>el.onclick=()=>{active=el.dataset.file;render();});
 const code=$('#code');if(code){code.oninput=()=>{files[active]=code.value;verified=null;lastResult=null;dirty=true;checkGeneration++;$('#line-numbers').innerHTML=code.value.split('\n').map((_,i)=>`<span>${i+1}</span>`).join('');$('#save-state').textContent='Saving…';clearTimeout(save.timer);save.timer=setTimeout(save,300);};code.onscroll=()=>$('#line-numbers').scrollTop=code.scrollTop;}}
function action(a){if(a==='export'){save();download('rejoin-project.json',JSON.stringify({workshop:'community-rsvp-v1',files},null,2));toast('Project exported. Import it from Privacy & settings.');}
 else if(a==='help'){if(room.paused){toast('Workshop paused. You can still edit and export.');return;}save();panel='consent';renderPanel();}
 else if(a==='hint'){panel='hint';renderPanel();}
 else if(a==='suggest'){try{plan=propose(files,target,protections);lastResult=null;panel='plan';renderPanel();}catch(e){toast(e.message);}}
 else if(a==='cancel'){panel='intro';plan=null;renderPanel();}
 else if(a==='check-candidate')checkCandidate();
 else if(a==='apply')apply();
 else if(a==='run')runChecks();
 else if(a==='protect'){protections=protections.includes(active)?protections.filter(x=>x!==active):[...protections,active];plan=null;panel='intro';save();render();}
 else if(a==='undo'){try{files=undoPlan(files,undo);undo=null;verified=null;plan=null;panel='intro';save();render();toast('Previous version restored.');}catch(e){if(undo){modal(`<h2>Your newer edits are safe.</h2><p>${esc(e.message)}</p><button id="old-copy" class="primary">Download pre-fix copy</button><button data-close class="quiet">Close</button>`);$('#old-copy').onclick=()=>download('rejoin-before-fix.json',JSON.stringify({files:JSON.parse(undo.before)},null,2));}else toast('No fix to undo yet.');}}
 else if(a==='lesson'){tab='lesson';render();}
 else if(a.startsWith('practice-')){target=a.slice(9);tab='workspace';panel='intro';render();}
 else if(a.startsWith('host-')){if(room.connection==='Connected'){toast('Use your broadcaster chat command to change the live checkpoint.');return;}room.checkpoint=a.slice(5);render();}
 else if(a==='pause'){if(room.connection==='Connected'){toast('Use !pause from your broadcaster account.');return;}room.paused=!room.paused;render();}
 else if(a==='answer')toast('Pass the function itself so it runs on click. register() would run immediately.');
 else if(a==='handoff')modal(`<span class="eyebrow">PRIVATE HANDOFF</span><h2>Ask with useful context.</h2><p>Download this packet and choose whom to send it to. Nothing is posted to Twitch.</p><label>Your question<textarea id="question" placeholder="What did you expect? What happened instead?"></textarea></label><p>Includes your three files, target ${target}, and the last check result. Review the downloaded file before sharing.</p><button class="primary" id="packet">Download help packet</button><button class="quiet" data-close>Cancel</button>`), a==='handoff'&&($('#packet').onclick=()=>{download('rejoin-help.json',JSON.stringify({question:$('#question').value,target,files,checks:lastResult},null,2));$('#dialog').close();});
 else if(a==='privacy')privacy();
 else if(a==='guide')modal(`<span class="eyebrow">WELCOME TO REJOIN</span><h2>A way back to building.</h2><ol><li>Personalize the event title or colors.</li><li>Use “Help me continue” for an authored hint.</li><li>Review and check the exact suggested fix.</li><li>Approve it. Try the RSVP button. Undo any time.</li></ol><p>Desktop is best for editing. Local saving is per browser: clearing storage removes progress. No cloud sync or runtime AI is enabled.</p><button data-close class="primary">Let’s build</button>`);
 else if(a==='twitch'){if(room.channel)window.open('https://www.twitch.tv/'+encodeURIComponent(room.channel),'_blank','noopener');else modal(`<h2>Bring your stream.</h2><p>Enter a public channel name to watch alongside Rejoin. This does not connect EventSub. See README for the local connector setup.</p><label>Twitch channel<input id="channel" placeholder="your_channel" pattern="[A-Za-z0-9_]{1,25}"></label><button id="watch" class="primary">Open Twitch ↗</button><button data-close class="quiet">Cancel</button>`),!room.channel&&($('#watch').onclick=()=>{const c=$('#channel').value.trim();if(!/^[a-zA-Z0-9_]{1,25}$/.test(c)){toast('Enter a valid Twitch channel name.');return;}room.channel=c;$('#dialog').close();window.open('https://www.twitch.tv/'+c,'_blank','noopener');});}}
function privacy(){modal(`<span class="eyebrow">PRIVATE BY DEFAULT</span><h2>Your code. Your choice.</h2><p>Files and undo history are saved only in this browser. No code uploads, model calls, analytics, or progress sharing. The Twitch connector reads host commands; it cannot access your files.</p><div class="settings-actions"><label class="secondary link-button">Import exported project<input id="import" type="file" accept=".json" hidden></label><button id="delete" class="danger">Delete local workspace</button></div><p>Import replaces this workspace only after confirmation. Export first to keep a copy.</p><button data-close class="quiet">Close</button>`);$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('Project is larger than 1 MB.');const data=JSON.parse(await file.text());validate(data.files);if(!confirm('Replace this workspace with the imported project? Export first if you need the current version.'))return;files=data.files;undo=null;verified=null;plan=null;panel='intro';save();$('#dialog').close();render();}catch(e){toast(e.message);}};$('#delete').onclick=()=>{if(!confirm('Delete locally saved code and undo history? This cannot be undone.'))return;clearTimeout(save.timer);localStorage.removeItem('rejoin.workspace');files=structuredClone(starter);protections=['style.css'];undo=null;verified=null;dirty=false;panel='intro';plan=null;$('#dialog').close();render();toast('Local workspace deleted. A fresh unsaved starter is open.');};}
// Only known workshop scripts may execute. HTML is allowlisted; CSS is isolated by CSP.
function previewDocument(bundle, testing=false, expected=target, nonce=''){
 validate(bundle);const kind=scriptKind(bundle['script.js']);const doc=new DOMParser().parseFromString(bundle['index.html'],'text/html');
 const allowed=new Set(['MAIN','DIV','SPAN','H1','H2','H3','P','BUTTON','SECTION','STRONG','EM','SMALL','BR']);
 for(const el of [...doc.body.querySelectorAll('*')]){if(!allowed.has(el.tagName)){el.remove();continue;}for(const attr of [...el.attributes])if(!['id','class','role','aria-live','aria-label','disabled'].includes(attr.name))el.removeAttribute(attr.name);}
 const css=bundle['style.css'].replace(/<\/style/gi,'');
 const js=kind==='unsupported'?'':bundle['script.js'];
 const harness=testing?`const button2=document.querySelector('button#rsvp');const count2=document.querySelector('#count');const status2=document.querySelector('#status');let checks=[{name:'Event title exists',pass:!!document.querySelector('h1')?.textContent.trim()}];if(${JSON.stringify(expected)}!=='C1'){button2?.click();checks.push({name:'RSVP registers once',pass:!!button2?.disabled&&button2?.textContent.includes("on the list")});checks.push({name:'Confirmation is announced',pass:!!status2?.textContent.includes('See you')&&status2?.getAttribute('aria-live')==='polite'});if(${JSON.stringify(expected)}==='C3'){button2?.click();checks.push({name:'Attendee count increments once',pass:count2?.textContent==='43'});}}parent.postMessage({type:'rejoin-check',nonce:${JSON.stringify(nonce)},checks},'*');`:'';
 return `<!doctype html><html><head><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'none'; connect-src 'none'; form-action 'none'; base-uri 'none'"><style>${css}</style></head><body>${doc.body.innerHTML}<script>${js}\n${harness}<\/script></body></html>`;
}
function updatePreview(){const frame=$('#preview');if(!frame)return;try{frame.srcdoc=previewDocument(files);$('#preview-state').textContent=scriptKind(files['script.js'])==='unsupported'?'Custom JavaScript not executed · preview only':'Prepared-workshop preview · click to try';}catch(e){$('#preview-state').textContent=e.message;}}
async function verify(bundle, expected){if(scriptKind(bundle['script.js'])==='unsupported')return {passed:false,message:'Not run: custom JavaScript is outside the restricted workshop runner.',checks:[]};
 return new Promise(resolve=>{const frame=document.createElement('iframe');frame.hidden=true;frame.sandbox='allow-scripts';const nonce=crypto.randomUUID();let timer;const done=result=>{clearTimeout(timer);window.removeEventListener('message',receive);frame.remove();resolve(result);};const receive=e=>{if(e.source!==frame.contentWindow||e.data?.type!=='rejoin-check'||e.data?.nonce!==nonce)return;const checks=e.data.checks;const passed=checks.every(c=>c.pass);done({passed,checks,message:passed?`${expected}: ${checks.length}/${checks.length} prepared-workshop checks passed. Custom title and styles are not assessed for visual quality.`:checks.filter(c=>!c.pass).map(c=>c.name+': failed').join(' · ')});};window.addEventListener('message',receive);timer=setTimeout(()=>done({passed:false,message:'Checks timed out. Result is inconclusive.',checks:[]}),2500);frame.srcdoc=previewDocument(bundle,true,expected,nonce);document.body.append(frame);});}
async function runChecks(){save();updatePreview();const revision=snapshot(files), selected=target, gen=++checkGeneration;toast('Checking the prepared workshop…');const result=await verify(structuredClone(files),selected);if(gen!==checkGeneration||snapshot(files)!==revision||target!==selected){toast('Code or target changed. Run checks again.');return;}lastResult=result;verified=result.passed?selected:null;save();toast(result.message);const state=$('#preview-state');if(state)state.textContent=result.message;}
async function checkCandidate(){if(!plan||plan.state!=='candidate')return;const captured=plan;const result=await verify(captured.files,captured.target);if(plan!==captured||snapshot(files)!==captured.before){toast('This suggestion is stale. Request a fresh review.');return;}lastResult={...result,candidate:captured.after};renderPanel();}
async function apply(){if(room.paused){toast('Workshop paused. Your suggestion has not been applied.');return;}try{if(!plan||!lastResult?.passed||lastResult.candidate!==plan.after){toast('Run the suggestion checks and resolve failures before applying.');return;}const approved=plan;files=applyPlan(files,approved);undo={before:approved.before,after:approved.after};verified=approved.target;panel='done';plan=null;save();render();toast('Approved fix applied. Your customizations are preserved.');}catch(e){toast(e.message);}}
render();
if(location.protocol.startsWith('http'))fetch('/api/room').then(r=>r.ok?r.json():null).then(data=>{if(!data)return;room=data;render();const source=new EventSource('/api/events');source.onmessage=e=>{try{room=JSON.parse(e.data);render();}catch{}};source.onerror=()=>{room.connection='Connector unavailable';const existing=$('footer');if(existing)existing.firstElementChild.textContent='Connector unavailable · local editing still works';};}).catch(()=>{});
